funcs_r = {'CCFFF': '$C-CF_3$',
         'CCHHH': '$C-CH_3$',
         'CCN': '$C-C\\equiv N$',
         'CCl': '$C-Cl$',
         'CF': '$C-F$',
         'CH': '$C-H$',
         'CNHH': '$C-NH_2$',
         'CNOO': '$C-NO_2$',
         'CCOOH': '$C-COOH$',
         'CO': '$C=O$',
         'COH': '$C-OH$',
         'CSH': '$C-SH$',
         'N': '$N$',
         'O': '$O$',
         'S': '$S$',
         'CNHCHHH' : '$CNHCH_3$',
         'COCHHH'  : '$COCH_3$' }
class Funcs(object):
    def __init__(self):
        self.funcs = funcs_r
    def __getitem__(self, key):
        try:
            ret = self.funcs[key]
        except KeyError:
            ret = '${}$'.format(key)
        return ret
funcs = Funcs()

class Cycle(object):
    def __init__(self, iterable):
        self.iterable = iterable
    def __getitem__(self,i):
        #assert isinstance(i, int), 'argument has to be an integer {}'.format(i)
        try:
            return self.iterable[ i % len(self.iterable) ]
        except TypeError:
            return self.iterable[ i ]
    def __iter__(self):
        return iter(self.iterable)
    def __len__(self):
        return len(self.iterable)

def indtocon(index):
    #return [list(item) for item in index.split('_')]
    #return  [ findall('[A-Z][^A-Z]*',item) for item in index.split('_') ]
    return  tuple( findall('[A-Z0-9][^A-Z1-9]*',item) for item in index.split('_') )

